14	func TestAValueOfHeaderValueWidthIsNeverClipped(t *testing.T) {
15		keys := []string{"Images", "Refused"}
16		for _, w := range []int{60, 80, 120, 200} {
17			n := shortcut.HeaderValueWidth(w, keys)
18			if n < 2 {
19				t.Fatalf("width %d: HeaderValueWidth = %d, the test needs a usable width", w, n)
20			}
21			render := func(cells int) string {
