27			}
28			if got := render(n); !strings.Contains(got, strings.Repeat("Q", n)) {
29				t.Errorf("width %d: a value of %d cells (HeaderValueWidth) was clipped:\n%s", w, n, got)
30			}
31			if got := render(n + 1); strings.Contains(got, strings.Repeat("Q", n+1)) {
32				t.Errorf("width %d: a value of %d cells was not clipped, so HeaderValueWidth is too small", w, n+1)
